function(container, apiUrl, tables) {
  const now = new Date();
  const formatTime = (d) => d.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  container.querySelector('#last-updated').textContent = formatTime(now);

  let allRecords = [];
  let allTests = [];
  let filteredRecords = [];
  let filteredTests = [];

  // データ取得
  async function loadData() {
    try {
      allRecords = await window.aivicApi.list(1) || [];
      allTests = await window.aivicApi.list(2) || [];
      applyFilter();
    } catch (e) {
      console.error('Data load error:', e);
    }
  }

  // フィルター適用
  function applyFilter() {
    const period = container.querySelector('[data-testid="period-filter"]').value;
    const now = new Date();
    let startDate = new Date(now.getFullYear(), now.getMonth(), 1);

    if (period === 'last-month') {
      startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    } else if (period === 'last-3-months') {
      startDate = new Date(now.getFullYear(), now.getMonth() - 3, 1);
    } else if (period === 'last-6-months') {
      startDate = new Date(now.getFullYear(), now.getMonth() - 6, 1);
    } else if (period === 'this-year') {
      startDate = new Date(now.getFullYear(), 0, 1);
    }

    filteredRecords = allRecords.filter(r => {
      const d = r.実装完了日 ? new Date(r.実装完了日) : new Date(r.作成日時);
      return d >= startDate;
    });

    filteredTests = allTests.filter(t => {
      const d = new Date(t.テスト実施日時);
      return d >= startDate;
    });

    updateDashboard();
  }

  // ダッシュボード更新
  function updateDashboard() {
    // 進捗率
    const completed = filteredRecords.filter(r => r.実装ステータス === '完了').length;
    const total = filteredRecords.length || 1;
    const percent = Math.round((completed / total) * 100);
    container.querySelector('#progress-percent').textContent = percent;
    container.querySelector('#progress-bar').style.width = percent + '%';
    container.querySelector('#progress-detail').textContent = `完了: ${completed} / 計画: ${total}`;

    // 実装状況の円グラフ
    const statusCounts = {
      '計画中': filteredRecords.filter(r => r.実装ステータス === '計画中').length,
      '実装中': filteredRecords.filter(r => r.実装ステータス === '実装中').length,
      '完了': filteredRecords.filter(r => r.実装ステータス === '完了').length,
      '保留中': filteredRecords.filter(r => r.実装ステータス === '保留中').length
    };
    drawPieChart(statusCounts);

    // JIS準拠項目（簡易: テスト結果から推定）
    const passedTests = filteredTests.filter(t => t.テスト結果 === '合格').length;
    const totalTests = filteredTests.length || 1;
    container.querySelector('#jis-achieved').textContent = passedTests;
    container.querySelector('#jis-pending').textContent = totalTests - passedTests;

    // ユーザーテスト結果
    container.querySelector('#test-count').textContent = filteredTests.length;
    const passRate = totalTests > 0 ? Math.round((passedTests / totalTests) * 100) : 0;
    container.querySelector('#test-pass-rate').textContent = passRate + '%';

    const avgSatisfaction = filteredTests.length > 0
      ? (filteredTests.reduce((sum, t) => sum + (t.満足度スコア || 0), 0) / filteredTests.length).toFixed(1)
      : '--';
    container.querySelector('#test-avg-satisfaction').textContent = avgSatisfaction + ' / 5.0';

    // 最近の実装記録（直近5件）
    const recent = filteredRecords.slice(0, 5);
    const recentHtml = recent.map(r => {
      const statusColor = {
        '完了': '#1a3a52',
        '実装中': '#6b6b6b',
        '計画中': '#d4cfc5',
        '保留中': '#d4cfc5'
      }[r.実装ステータス] || '#6b6b6b';

      return `
        <div data-record-id="${r.改善実装記録ID}" style="padding: 10px; border: 1px solid var(--border); border-radius: 3px; cursor: pointer; transition: background 200ms; background: var(--bg-card);" onmouseover="this.style.background='rgba(26,58,82,0.05)'" onmouseout="this.style.background='var(--bg-card)'">
          <p style="font-size: 12px; font-weight: 500; color: var(--text); margin: 0 0 4px 0;">${r.改善項目名 || '(無名)'}</p>
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <span style="font-size: 11px; color: #fff; background: ${statusColor}; padding: 2px 6px; border-radius: 2px;">${r.実装ステータス || '--'}</span>
            <span style="font-size: 11px; color: var(--text-muted);">${r.実装完了日 ? new Date(r.実装完了日).toLocaleDateString('ja-JP') : '--'}</span>
          </div>
        </div>
      `;
    }).join('');
    container.querySelector('#recent-records').innerHTML = recentHtml || '<p style="color: var(--text-muted); font-size: 12px;">記録なし</p>';

    // 最近の実装記録クリックイベント
    container.querySelectorAll('[data-record-id]').forEach(el => {
      el.addEventListener('click', () => {
        const recordId = el.dataset.recordId;
        const record = allRecords.find(r => r.改善実装記録ID === recordId);
        if (record) showDetailModal('改善実装記録', record);
      });
    });
  }

  // 円グラフ描画
  function drawPieChart(statusCounts) {
    const canvas = container.querySelector('#status-chart');
    const ctx = canvas.getContext('2d');
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = 60;

    const colors = {
      '完了': '#1a3a52',
      '実装中': '#6b6b6b',
      '計画中': '#d4cfc5',
      '保留中': '#e8e3d8'
    };

    const total = Object.values(statusCounts).reduce((a, b) => a + b, 0) || 1;
    let currentAngle = -Math.PI / 2;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    Object.entries(statusCounts).forEach(([status, count]) => {
      const sliceAngle = (count / total) * 2 * Math.PI;
      ctx.fillStyle = colors[status] || '#999';
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.lineTo(centerX, centerY);
      ctx.fill();
      currentAngle += sliceAngle;
    });

    // 凡例
    const legendHtml = Object.entries(statusCounts).map(([status, count]) => `
      <div style="display: flex; align-items: center; gap: 6px;">
        <div style="width: 10px; height: 10px; background: ${colors[status] || '#999'}; border-radius: 2px;"></div>
        <span style="color: var(--text);">${status}: ${count}</span>
      </div>
    `).join('');
    container.querySelector('#status-legend').innerHTML = legendHtml;
  }

  // 詳細モーダル表示
  function showDetailModal(title, data) {
    const modal = container.querySelector('#detail-modal-overlay');
    const titleEl = container.querySelector('#detail-modal-title');
    const contentEl = container.querySelector('#detail-modal-content');

    titleEl.textContent = title;

    let html = '';
    if (data.改善項目名) {
      // 改善実装記録
      html = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
          <div><strong>改善項目名:</strong> ${data.改善項目名 || '--'}</div>
          <div><strong>ステータス:</strong> ${data.実装ステータス || '--'}</div>
          <div><strong>対象UI要素:</strong> ${data.対象UI要素 || '--'}</div>
          <div><strong>優先度:</strong> ${data.優先度 || '--'}</div>
          <div><strong>実装予定日:</strong> ${data.実装予定日 ? new Date(data.実装予定日).toLocaleDateString('ja-JP') : '--'}</div>
          <div><strong>実装完了日:</strong> ${data.実装完了日 ? new Date(data.実装完了日).toLocaleDateString('ja-JP') : '--'}</div>
          <div><strong>テスト実施状況:</strong> ${data.テスト実施状況 || '--'}</div>
          <div><strong>テスト参加者数:</strong> ${data.テスト参加者数 || '--'}</div>
        </div>
        <div style="margin-top: 12px;">
          <strong>改善内容:</strong>
          <p style="margin: 4px 0; white-space: pre-wrap; color: var(--text-muted);">${data.改善内容 || '--'}</p>
        </div>
        <div style="margin-top: 12px;">
          <strong>テスト結果:</strong>
          <p style="margin: 4px 0; white-space: pre-wrap; color: var(--text-muted);">${data.テスト結果 || '--'}</p>
        </div>
        <div style="margin-top: 12px;">
          <strong>改善効果:</strong>
          <p style="margin: 4px 0; white-space: pre-wrap; color: var(--text-muted);">${data.改善効果 || '--'}</p>
        </div>
      `;
    } else if (data.テスト種別) {
      // ユーザーテスト
      html = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
          <div><strong>テスト種別:</strong> ${data.テスト種別 || '--'}</div>
          <div><strong>テスト結果:</strong> ${data.テスト結果 || '--'}</div>
          <div><strong>実施日時:</strong> ${data.テスト実施日時 ? new Date(data.テスト実施日時).toLocaleString('ja-JP') : '--'}</div>
          <div><strong>所要時間:</strong> ${data.所要時間秒 ? data.所要時間秒 + '秒' : '--'}</div>
          <div><strong>満足度スコア:</strong> ${data.満足度スコア || '--'} / 5</div>
        </div>
        <div style="margin-top: 12px;">
          <strong>ユーザーフィードバック:</strong>
          <p style="margin: 4px 0; white-space: pre-wrap; color: var(--text-muted);">${data.ユーザーフィードバック || '--'}</p>
        </div>
        <div style="margin-top: 12px;">
          <strong>問題点摘出:</strong>
          <p style="margin: 4px 0; white-space: pre-wrap; color: var(--text-muted);">${data.問題点摘出 || '--'}</p>
        </div>
        <div style="margin-top: 12px;">
          <strong>改善提案:</strong>
          <p style="margin: 4px 0; white-space: pre-wrap; color: var(--text-muted);">${data.改善提案 || '--'}</p>
        </div>
      `;
    }

    contentEl.innerHTML = html;
    modal.style.display = 'flex';
  }

  // モーダル閉じるボタン
  container.querySelector('#detail-modal-close').addEventListener('click', () => {
    container.querySelector('#detail-modal-overlay').style.display = 'none';
  });

  // overlay クリックで閉じる
  container.querySelector('#detail-modal-overlay').addEventListener('click', (e) => {
    if (e.target.id === 'detail-modal-overlay') {
      e.target.style.display = 'none';
    }
  });

  // Esc キーで閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      container.querySelector('#detail-modal-overlay').style.display = 'none';
    }
  });

  // フィルター変更イベント
  container.querySelector('[data-testid="period-filter"]').addEventListener('change', applyFilter);

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  const tableIndex = 0; // UI改善実装記録テーブル
  const userTableIndex = 1; // ユーザーテーブル

  const form = container.querySelector('#improvement-form');
  const tbody = container.querySelector('#improvement-tbody');
  const createBtn = container.querySelector('[data-testid="create-improvement-button"]');
  const saveBtn = container.querySelector('[data-testid="save-improvement-button"]');
  const cancelBtn = container.querySelector('[data-testid="cancel-improvement-button"]');
  const createModal = container.querySelector('#create-modal');
  const modalConfirmBtn = container.querySelector('[data-testid="modal-confirm-button"]');
  const modalCancelBtn = container.querySelector('[data-testid="modal-cancel-button"]');
  const errorMsg = container.querySelector('#error-message');
  const successMsg = container.querySelector('#success-message');

  let currentEditId = null;
  let allRecords = [];
  let allUsers = [];

  // ユーティリティ: メッセージ表示
  function showError(text) {
    container.querySelector('#error-text').textContent = text;
    errorMsg.style.display = 'block';
    setTimeout(() => { errorMsg.style.display = 'none'; }, 4000);
  }

  function showSuccess(text) {
    container.querySelector('#success-text').textContent = text;
    successMsg.style.display = 'block';
    setTimeout(() => { successMsg.style.display = 'none'; }, 3000);
  }

  // ユーティリティ: ステータスバッジ色
  function getStatusBadgeStyle(status) {
    const styles = {
      'not_started': 'background: #f5f5f5; color: #666;',
      'in_progress': 'background: #fff3cd; color: #856404;',
      'completed': 'background: #e8f5e9; color: #2e7d32;'
    };
    return styles[status] || 'background: #f5f5f5; color: #666;';
  }

  function getStatusLabel(status) {
    const labels = {
      'not_started': '未実装',
      'in_progress': '実装中',
      'completed': '完了'
    };
    return labels[status] || status;
  }

  function getPriorityLabel(priority) {
    const labels = {
      'high': '高',
      'medium': '中',
      'low': '低'
    };
    return labels[priority] || priority;
  }

  // ユーティリティ: ユーザー名取得
  function getUserName(userId) {
    const user = allUsers.find(u => u.id === userId);
    return user ? user.name : '未割当';
  }

  // 一覧表をリロード
  async function loadRecords() {
    const records = await window.aivicApi.list(tableIndex);
    if (!records) {
      showError('改善施策の読み込みに失敗しました');
      return;
    }
    allRecords = records;
    renderTable();
  }

  // ユーザー一覧をロード
  async function loadUsers() {
    const users = await window.aivicApi.list(userTableIndex);
    if (users) {
      allUsers = users;
      updateAssigneeSelect();
    }
  }

  // 担当者セレクトを更新
  function updateAssigneeSelect() {
    const select = form.querySelector('[name="assignee_id"]');
    const currentValue = select.value;

    // 既存の option を削除（プレースホルダー以外）
    while (select.options.length > 1) {
      select.remove(1);
    }

    // ユーザーを追加
    allUsers.forEach(user => {
      const option = document.createElement('option');
      option.value = user.id;
      option.textContent = user.name;
      select.appendChild(option);
    });

    select.value = currentValue;
  }

  // テーブルをレンダリング
  function renderTable() {
    tbody.innerHTML = '';
    allRecords.forEach(record => {
      const row = document.createElement('tr');
      row.className = 'improvement-row';
      row.dataset.id = record.id;
      row.style.cssText = 'background: var(--bg-card); border-bottom: 1px solid var(--border); cursor: pointer; transition: background-color 200ms;';
      row.innerHTML = `
        <td style="padding: 10px 12px; color: var(--text-muted); border-right: 1px solid var(--border);">${record.id.substring(0, 8)}</td>
        <td style="padding: 10px 12px; color: var(--text); border-right: 1px solid var(--border); font-weight: 500;">${record.title || '（未入力）'}</td>
        <td style="padding: 10px 12px; color: var(--text); border-right: 1px solid var(--border);">
          <span style="display: inline-block; padding: 2px 8px; background: ${record.priority === 'high' ? 'var(--primary)' : record.priority === 'medium' ? '#fff3cd' : '#f5f5f5'}; color: ${record.priority === 'high' ? '#fff' : record.priority === 'medium' ? '#856404' : '#666'}; border-radius: 3px; font-size: 12px;">
            ${getPriorityLabel(record.priority)}
          </span>
        </td>
        <td style="padding: 10px 12px; color: var(--text); border-right: 1px solid var(--border);">
          <span style="display: inline-block; padding: 2px 8px; ${getStatusBadgeStyle(record.status)}; border-radius: 3px; font-size: 12px;">
            ${getStatusLabel(record.status)}
          </span>
        </td>
        <td style="padding: 10px 12px; color: var(--text-muted);">${getUserName(record.assignee_id)}</td>
      `;
      row.addEventListener('click', () => loadFormData(record));
      tbody.appendChild(row);
    });
  }

  // フォームにデータをロード
  function loadFormData(record) {
    currentEditId = record.id;
    form.querySelector('[name="title"]').value = record.title || '';
    form.querySelector('[name="description"]').value = record.description || '';
    form.querySelector('[name="accessibility_item"]').value = record.accessibility_item || '';
    form.querySelector('[name="priority"]').value = record.priority || '';
    form.querySelector('[name="assignee_id"]').value = record.assignee_id || '';
    form.querySelector('[name="planned_date"]').value = record.planned_date ? record.planned_date.split('T')[0] : '';
    form.querySelector('[name="status"]').value = record.status || '';

    // チェックリストをリセット
    container.querySelectorAll('#validation-checklist input[type="checkbox"]').forEach(cb => {
      cb.checked = false;
    });
  }

  // フォームをリセット
  function resetForm() {
    currentEditId = null;
    form.reset();
    container.querySelectorAll('#validation-checklist input[type="checkbox"]').forEach(cb => {
      cb.checked = false;
    });
  }

  // フォーム送信
  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    const formData = {
      title: form.querySelector('[name="title"]').value.trim(),
      description: form.querySelector('[name="description"]').value.trim(),
      accessibility_item: form.querySelector('[name="accessibility_item"]').value,
      priority: form.querySelector('[name="priority"]').value,
      assignee_id: form.querySelector('[name="assignee_id"]').value,
      planned_date: form.querySelector('[name="planned_date"]').value,
      status: form.querySelector('[name="status"]').value
    };

    if (!formData.title) {
      showError('施策タイトルを入力してください');
      return;
    }
    if (!formData.priority) {
      showError('優先度を選択してください');
      return;
    }
    if (!formData.status) {
      showError('実装ステータスを選択してください');
      return;
    }

    let result;
    if (currentEditId) {
      result = await window.aivicApi.update(tableIndex, currentEditId, formData);
    } else {
      result = await window.aivicApi.save(tableIndex, formData);
    }

    if (result) {
      showSuccess(currentEditId ? '改善施策を更新しました' : '改善施策を登録しました');
      resetForm();
      await loadRecords();
    } else {
      showError('保存に失敗しました');
    }
  });

  // キャンセルボタン
  cancelBtn.addEventListener('click', () => {
    resetForm();
  });

  // 新規登録ボタン
  createBtn.addEventListener('click', () => {
    createModal.style.display = 'flex';
  });

  // モーダル確認ボタン
  modalConfirmBtn.addEventListener('click', () => {
    resetForm();
    createModal.style.display = 'none';
    form.querySelector('[name="title"]').focus();
  });

  // モーダルキャンセルボタン
  modalCancelBtn.addEventListener('click', () => {
    createModal.style.display = 'none';
  });

  // モーダル背景クリックで閉じる
  createModal.addEventListener('click', (e) => {
    if (e.target === createModal) {
      createModal.style.display = 'none';
    }
  });

  // Esc キーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && createModal.style.display === 'flex') {
      createModal.style.display = 'none';
    }
  });

  // 初期化
  (async () => {
    await loadUsers();
    await loadRecords();
  })();
}
